from netmiko import ConnectHandler
import sys

ROUTERS = {
    "HQ": "192.168.122.6",
    "Branch1": "192.168.122.5",
    "Branch2": "192.168.122.7",
}

CMDS = [
    "show interfaces",
    "show ip ospf neighbor",
    "show ip route",
    "show configuration commands | grep ospf",
    "show configuration commands | grep interfaces ethernet",
    "show configuration commands | grep 'protocols static'",
]

def run(name, host):
    dev = {"device_type": "vyos", "host": host, "username": "vyos", "password": "test"}
    try:
        c = ConnectHandler(**dev)
        out = []
        for cmd in CMDS:
            out.append(f"\n=== {name} $ {cmd} ===\n" + c.send_command(cmd))
        c.disconnect()
        return "\n".join(out)
    except Exception as e:
        return f"ERR {name}: {e}"

if __name__ == "__main__":
    target = sys.argv[1] if len(sys.argv) > 1 else None
    for n, h in ROUTERS.items():
        if target and n != target:
            continue
        print(run(n, h))

