from netmiko import ConnectHandler

TESTS = {
    "HQ": ("192.168.122.6", [
        "ping 10.10.5.254 source-address 10.10.0.1 count 2",
        "ping 10.10.7.254 source-address 10.10.0.1 count 2",
    ]),
    "Branch1": ("192.168.122.5", [
        "ping 10.10.3.254 source-address 10.10.4.1 count 2",
        "ping 10.10.7.254 source-address 10.10.4.1 count 2",
