        "ping 10.10.5.254 source-address 10.10.6.1 count 2",
        "ping 10.10.3.254 source-address 10.10.6.1 count 2",
        "ping 209.165.202.129 source-address 10.10.6.1 count 2",
    ]),
}

for n, (h, cmds) in TESTS.items():
